  latestAuditIntegrityHash(){const rows=this.db.prepare('SELECT payload_json FROM audit_events ORDER BY rowid DESC').all();for(const r of rows){const e=parse(r.payload_json);if(e?.integrity?.eventHash)return e.integrity.eventHash}return null}
  audit(action,entityType,entityId,metadata={},actor={actorId:'server-local',displayName:'PRO4X4 Local Server',role:'admin'},correlationId=null){const base={schemaVersion:SCHEMA_VERSION,id:eventId(),at:now(),action,entityType,entityId:String(entityId||''),actor,correlationId,metadata:clone(metadata)},e=auditIntegrity.seal(base,this.latestAuditIntegrityHash());this.db.prepare('INSERT INTO audit_events(id,at,action,entity_type,entity_id,actor_role,actor_id,correlation_id,payload_json) VALUES(?,?,?,?,?,?,?,?,?)').run(e.id,e.at,e.action,e.entityType,e.entityId,e.actor.role,e.actor.actorId,e.correlationId,stringify(e));return e}
  listAudit({entityType=null,entityId=null,action=null,limit=200}={}){let sql='SELECT payload_json FROM audit_events WHERE 1=1',args=[];if(entityType){sql+=' AND entity_type=?';args.push(entityType)}if(entityId){sql+=' AND entity_id=?';args.push(entityId)}if(action){sql+=' AND action=?';args.push(action)}sql+=' ORDER BY at DESC, rowid DESC LIMIT ?';args.push(Math.max(1,Math.min(Number(limit)||200,1000)));return this.db.prepare(sql).all(...args).map(r=>parse(r.payload_json)).filter(Boolean)}
